package org.example.api.bank;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.example.config.ConfigManager;

import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;

public final class BankStatementApiClient {
 private final HttpClient http = org.example.api.ApiRuntime.HTTP;
 private final ObjectMapper json = org.example.api.ApiRuntime.JSON;
 private final String base;
 public BankStatementApiClient(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);base=b;}
 public ImportResult importStatement(ImportRequest r){return post("/api/bank-statements/imports",r,ImportResult.class);} public BatchDeleteResult deleteBatch(long id,String confirmation,String user){return delete("/api/bank-statements/imports/"+id+"?confirmation="+enc(confirmation)+"&user="+enc(user),BatchDeleteResult.class);} public List<BatchDto>batches(){return batchPage(0,20,"","","","","").rows();} public BatchDto batch(long id){return get("/api/bank-statements/imports/"+id,BatchDto.class);} public BatchPage batchPage(int page,int size,String account,String status,String fromDate,String toDate,String q){String path="/api/bank-statements/imports/page?page="+Math.max(0,page)+"&size="+Math.max(10,Math.min(size,100))+"&account="+enc(account)+"&status="+enc(status)+"&fromDate="+enc(fromDate)+"&toDate="+enc(toDate)+"&q="+enc(q);return get(path,BatchPage.class);} public SourceDto source(long id){return get("/api/bank-statements/imports/"+id+"/source",SourceDto.class);} public List<TransactionDto>transactions(long id){return get("/api/bank-statements/imports/"+id+"/transactions",new TypeReference<List<TransactionDto>>(){});} public TransactionDto transaction(long id){return get("/api/bank-statements/transactions/"+id,TransactionDto.class);} public Metrics metrics(long id){return get("/api/bank-statements/imports/"+id+"/metrics",Metrics.class);} public TransactionPage page(long id,int page,int size,String status,String direction,String fromDate,String toDate,String q){String path="/api/bank-statements/imports/"+id+"/page?page="+Math.max(0,page)+"&size="+Math.max(10,Math.min(size,100))+"&status="+enc(status)+"&direction="+enc(direction)+"&fromDate="+enc(fromDate)+"&toDate="+enc(toDate)+"&q="+enc(q);return get(path,TransactionPage.class);} public List<CandidateDto>suggest(long id){return post("/api/bank-statements/transactions/"+id+"/suggest",null,new TypeReference<List<CandidateDto>>(){});} public List<CandidateDto>candidates(long id){return get("/api/bank-statements/transactions/"+id+"/candidates",new TypeReference<List<CandidateDto>>(){});} public OperationResult match(long id,MatchRequest r){return post("/api/bank-statements/transactions/"+id+"/match",r,OperationResult.class);} public OperationResult expense(long id,ExpenseRequest r){return post("/api/bank-statements/transactions/"+id+"/expense",r,OperationResult.class);} public OperationResult bankEntry(long id,BankEntryRequest r){return post("/api/bank-statements/transactions/"+id+"/bank-entry",r,OperationResult.class);} public BulkOperationResult bulkExpense(BulkExpenseRequest r){return post("/api/bank-statements/transactions/bulk/expense",r,BulkOperationResult.class);} public BulkOperationResult bulkBankEntry(BulkBankEntryRequest r){return post("/api/bank-statements/transactions/bulk/bank-entry",r,BulkOperationResult.class);} public OperationResult updateNote(long id,NoteRequest r){return post("/api/bank-statements/transactions/"+id+"/note",r,OperationResult.class);} public OperationResult ignore(long id,IgnoreRequest r){return post("/api/bank-statements/transactions/"+id+"/ignore",r,OperationResult.class);} public OperationResult review(long id,NoteRequest r){return post("/api/bank-statements/transactions/"+id+"/review",r,OperationResult.class);} public OperationResult reverse(long id,String user){return post("/api/bank-statements/transactions/"+id+"/reverse?user="+enc(user),null,OperationResult.class);} public List<AuditDto>audit(long id){return get("/api/bank-statements/transactions/"+id+"/audit",new TypeReference<List<AuditDto>>(){});}
 private <T>T get(String p,Class<T>c){return req("GET",p,null,c,null);} private <T>T get(String p,TypeReference<T>t){return req("GET",p,null,null,t);} private <T>T post(String p,Object b,Class<T>c){return req("POST",p,b,c,null);} private <T>T post(String p,Object b,TypeReference<T>t){return req("POST",p,b,null,t);} private <T>T delete(String p,Class<T>c){return req("DELETE",p,null,c,null);}
 private <T>T req(String method,String path,Object body,Class<T>c,TypeReference<T>t){try{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");org.example.api.ApiSession.authorize(b);if(body!=null)b.header("Content-Type","application/json");String payload=body==null?"":json.writeValueAsString(body);b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(payload,StandardCharsets.UTF_8));HttpResponse<String>r=http.send(b.build(),HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));if(r.statusCode()/100!=2){org.example.api.ApiRuntime.logHttpFailure("Bank Statement request",r.statusCode(),r.body());throw new IllegalStateException(org.example.api.ApiRuntime.userMessage("the Bank Statement request",r.statusCode(),r.body()));}if(c!=null)return json.readValue(r.body(),c);return json.readValue(r.body(),t);}catch(Exception e){if(e instanceof RuntimeException re)throw re;throw new IllegalStateException("Cannot reach Bank Statement API at "+base+": "+e.getMessage(),e);}}
 private static String enc(String s){return URLEncoder.encode(s==null?"":s,StandardCharsets.UTF_8);}
 public record ImportRow(Integer sourceRowNumber,String transactionTimestamp,String transactionDate,String valueDate,String description,String reference,double debit,double credit,double balance,String transactionFingerprint){}
 public record ImportRequest(String bankName,String bankAccount,String accountHolder,String statementFrom,String statementTo,String currency,Double openingBalance,Double closingBalance,String sourceFingerprint,String sourceFileName,String sourceCsv,String importedBy,boolean dryRun,List<ImportRow> rows){}
 public record ImportResult(BatchDto batch,int importedRows,int duplicateRows,boolean alreadyImported){}
 public record BatchDto(Long id,String bankName,String bankAccount,String accountHolder,String statementFrom,String statementTo,String currency,int transactionCount,double totalDebit,double totalCredit,int reconciledCount,double reconciliationPercent,String status,String sourceFileName,String importedAt){@Override public String toString(){String account=bankAccount==null?"":bankAccount;String tail=account.length()>4?"****"+account.substring(account.length()-4):account;return bankName+" • "+tail+" • "+statementFrom+" to "+statementTo+" • "+status;}}
 public record BatchPage(List<BatchDto> rows,int page,int size,long totalRows,int totalPages){}
 public record SourceDto(String fileName,String fingerprint,String csvContent){} public record TransactionPage(List<TransactionDto> rows,Metrics metrics,int page,int size,long totalRows,int totalPages){} public record AllocationDto(Long allocationId,String targetType,Integer targetId,String documentNo,double allocatedAmount,double roundingAdjustment,Integer paymentRecordId,Integer financeEntryId){} public record TransactionDto(Long id,Long importId,Integer sourceRowNumber,String transactionTimestamp,String transactionDate,String valueDate,String description,String reference,double debit,double credit,double balance,String status,String suggestedMatchType,Integer suggestedMatchId,Double suggestedConfidence,String matchLink,Integer financeEntryId,String linkedTargetType,Integer linkedTargetId,String linkedDocumentNo,List<AllocationDto> linkedAllocations){}
 public record CandidateDto(String type,Integer id,String documentNo,String partyName,String documentDate,double totalAmount,double paidAmount,double outstanding,double confidence){@Override public String toString(){return type+" • "+documentNo+" • "+partyName+" • Outstanding "+String.format(Locale.ENGLISH,"%,.2f",outstanding)+" • "+String.format(Locale.ENGLISH,"%.0f%%",confidence);}}
 public record AllocationRequest(String targetType,Integer targetId,double amount){} public record MatchRequest(String user,List<AllocationRequest> allocations){} public record BatchDeleteResult(boolean success,String message,long deletedBatchId,int deletedTransactions,int reversedTransactions){} public record ExpenseRequest(String category,String accountName,String paymentMode,String notes,String billPath,String user){} public record BankEntryRequest(String accountName,String paymentMode,String notes,String user){} public record BulkExpenseRequest(List<Long> transactionIds,String category,String accountName,String paymentMode,String notes,String billPath,String user){} public record BulkBankEntryRequest(List<Long> transactionIds,String accountName,String paymentMode,String notes,String user){} public record BulkOperationResult(boolean success,String message,String status,int processed,List<Integer> financeEntryIds){} public record IgnoreRequest(String note,String user){} public record NoteRequest(String note,String user){} public record OperationResult(boolean success,String message,String status,Integer financeEntryId){} public record AuditDto(Long id,String eventType,String detail,String previousStatus,String newStatus,String performedBy,String createdAt){} public record Metrics(int total,int unmatched,int suggested,int matched,int expenses,int ignored,int review,double totalCredits,double totalDebits,int reconciled,double reconciledPercent,String batchStatus){}
}
